CREATE TABLE manual_recharge_config (id INT PRIMARY KEY,document LONGTEXT NOT NULL) ENGINE=InnoDB;
CREATE TABLE manual_recharge_assets (id VARCHAR(36) PRIMARY KEY,mime_type VARCHAR(50) NOT NULL,image_bytes MEDIUMBLOB NOT NULL,created_at VARCHAR(32) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE manual_recharge_orders (id VARCHAR(36) PRIMARY KEY,user_id VARCHAR(191) COLLATE utf8mb4_bin NOT NULL,user_name VARCHAR(191) NOT NULL,package_name VARCHAR(100) NOT NULL,price_cents BIGINT NOT NULL CHECK(price_cents>0),credits BIGINT NOT NULL CHECK(credits BETWEEN 1 AND 1000000000),channel VARCHAR(16) NOT NULL CHECK(channel IN ('alipay','wechat')),delivery VARCHAR(16) NOT NULL CHECK(delivery IN ('direct','code')),status VARCHAR(16) NOT NULL CHECK(status IN ('created','pending','approved','rejected','cancelled')),qr_asset_id VARCHAR(36) NOT NULL,receiver_name VARCHAR(100) NOT NULL,proof_asset_id VARCHAR(36),note VARCHAR(1000) NOT NULL DEFAULT '',reason VARCHAR(1000) NOT NULL DEFAULT '',created_at VARCHAR(32) NOT NULL,submitted_at VARCHAR(32),reviewed_at VARCHAR(32),reviewed_by VARCHAR(191),encrypted_code TEXT,FOREIGN KEY(qr_asset_id) REFERENCES manual_recharge_assets(id),FOREIGN KEY(proof_asset_id) REFERENCES manual_recharge_assets(id),INDEX manual_recharge_user(user_id,status,created_at),INDEX manual_recharge_status(status,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

